// Cells that a falling object slides off (rounded tops)
const ROUNDED = new Set([T.ROCK, T.BALL, T.GATE, T.WALL]);
const HEAVY = new Set([T.ROCK, T.BALL]);
const MONSTERS = new Set([T.FISH, T.JELLY, T.CRAB]);

