  isWater(x, y) { if (x < 0 || y < 0 || x >= this.w || y >= this.h) return false; return this.water[y * this.w + x] === 1; }
  get(x, y) { if (x < 0 || y < 0 || x >= this.w || y >= this.h) return T.STEEL; return this.grid[y * this.w + x]; }
